Reply to Email.code:
// Send a reply in an existing conversation.
// sendMessage() can't set threadId or reply headers, so call the Gmail API directly.
fn(async state => {
  // Reply headers: threadId plus In-Reply-To/References (the original's Message-ID header)
  // keep the reply in the same conversation.
  const raw = Buffer.from(
    [
      `To: ${state.data.from}`,
      `Subject: Re: ${state.data.subject}`,
      `In-Reply-To: ${state.data.rfcMessageId}`,
      `References: ${state.data.rfcMessageId}`,
      'Content-Type: text/plain; charset=UTF-8',
      '',
      state.data.replyBody,
    ].join('\r\n')
  ).toString('base64url');

  const res = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/messages/send`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ raw, threadId: state.data.threadId }),
  });
  if (!res.ok) throw new Error(`Gmail API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

