Find Email.code:
// Find emails matching a Gmail search query.
// Results land on state.data as an array of message contents.
getContentsFromMessages({
  // Standard Gmail search syntax (from:, subject:, after:, has:attachment, ...).
  query: 'from:billing@example.org subject:invoice after:2026/01/01',
  // Which fields to pull back per message.
  contents: ['from', 'date', 'subject', 'body'],
  // Cap the number of messages returned.
  maxResults: 25,
});

Get Attachment by Filename.code:
// Find the latest email with a given attachment and pull that file's contents.
getContentsFromMessages({
  // Gmail search syntax: narrow to messages carrying this filename.
  query: `has:attachment filename:${$.data.fileName}`,
  contents: [
    'subject',
    // `file` matches the attachment name (string or RegExp); `name` is the output key.
    { type: 'file', name: 'attachment', file: $.data.fileName },
  ],
  maxResults: 1,
});
